BEGIN;
CREATE TABLE IF NOT EXISTS users(id SERIAL PRIMARY KEY,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,name TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'user',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS pm_organizations(id BIGSERIAL PRIMARY KEY,name TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS pm_products(id BIGSERIAL PRIMARY KEY,organization_id BIGINT NOT NULL REFERENCES pm_organizations(id),name TEXT NOT NULL,confidentiality TEXT NOT NULL DEFAULT 'internal' CHECK(confidentiality IN('internal','confidential')),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(organization_id,name));
CREATE TABLE IF NOT EXISTS pm_memberships(organization_id BIGINT NOT NULL REFERENCES pm_organizations(id),product_id BIGINT NOT NULL REFERENCES pm_products(id),user_id INTEGER NOT NULL REFERENCES users(id),role TEXT NOT NULL CHECK(role IN('researcher','product_manager','product_approver','delivery_operator','auditor','admin')),active BOOLEAN NOT NULL DEFAULT TRUE,can_view_confidential BOOLEAN NOT NULL DEFAULT FALSE,can_publish_confidential BOOLEAN NOT NULL DEFAULT FALSE,PRIMARY KEY(organization_id,product_id,user_id));
CREATE TABLE IF NOT EXISTS pm_workspace_versions(id BIGSERIAL PRIMARY KEY,organization_id BIGINT NOT NULL REFERENCES pm_organizations(id),product_id BIGINT NOT NULL REFERENCES pm_products(id),idempotency_key TEXT NOT NULL,version INTEGER NOT NULL CHECK(version>0),graph JSONB NOT NULL,graph_digest CHAR(64) NOT NULL,created_by INTEGER NOT NULL REFERENCES users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(organization_id,product_id,idempotency_key),UNIQUE(organization_id,product_id,version),UNIQUE(organization_id,product_id,graph_digest));
CREATE TABLE IF NOT EXISTS pm_domain_entities(id BIGSERIAL PRIMARY KEY,organization_id BIGINT NOT NULL REFERENCES pm_organizations(id),product_id BIGINT NOT NULL REFERENCES pm_products(id),workspace_version_id BIGINT NOT NULL REFERENCES pm_workspace_versions(id),entity_kind TEXT NOT NULL CHECK(entity_kind IN('productAreas','outcomes','opportunities','experiments','roadmapItems','releases','decisions')),entity_ref TEXT NOT NULL,payload JSONB NOT NULL,payload_digest CHAR(64) NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(organization_id,product_id,workspace_version_id,entity_kind,entity_ref));
CREATE TABLE IF NOT EXISTS pm_ownership_links(id BIGSERIAL PRIMARY KEY,organization_id BIGINT NOT NULL REFERENCES pm_organizations(id),product_id BIGINT NOT NULL REFERENCES pm_products(id),workspace_version_id BIGINT NOT NULL REFERENCES pm_workspace_versions(id),entity_ref TEXT NOT NULL,owner_user_id INTEGER NOT NULL REFERENCES users(id),ownership_role TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(organization_id,product_id,workspace_version_id,entity_ref,owner_user_id,ownership_role));
CREATE TABLE IF NOT EXISTS pm_evidence(id BIGSERIAL PRIMARY KEY,organization_id BIGINT NOT NULL REFERENCES pm_organizations(id),product_id BIGINT NOT NULL REFERENCES pm_products(id),idempotency_key TEXT NOT NULL,provider TEXT NOT NULL,external_id TEXT NOT NULL,external_version TEXT NOT NULL,evidence_kind TEXT NOT NULL,captured_at TIMESTAMPTZ NOT NULL,source_digest CHAR(64) NOT NULL,evidence_digest CHAR(64) NOT NULL,feedback_fingerprint CHAR(64),confidential BOOLEAN NOT NULL DEFAULT FALSE,access_class TEXT NOT NULL,retention_class TEXT NOT NULL,payload JSONB NOT NULL,created_by INTEGER NOT NULL REFERENCES users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(organization_id,product_id,idempotency_key),UNIQUE(organization_id,product_id,provider,external_id,external_version),UNIQUE(organization_id,product_id,evidence_digest));
CREATE UNIQUE INDEX IF NOT EXISTS pm_feedback_dedupe_idx ON pm_evidence(organization_id,product_id,feedback_fingerprint) WHERE feedback_fingerprint IS NOT NULL;
CREATE TABLE IF NOT EXISTS pm_sync_conflicts(id BIGSERIAL PRIMARY KEY,organization_id BIGINT NOT NULL REFERENCES pm_organizations(id),product_id BIGINT NOT NULL REFERENCES pm_products(id),provider TEXT NOT NULL,external_id TEXT NOT NULL,existing_evidence_id BIGINT NOT NULL REFERENCES pm_evidence(id),incoming_payload JSONB NOT NULL,conflict_digest CHAR(64) NOT NULL,status TEXT NOT NULL CHECK(status IN('open','resolved_keep_existing','resolved_accept_new')),resolved_by INTEGER REFERENCES users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),resolved_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS pm_opportunity_scores(id BIGSERIAL PRIMARY KEY,organization_id BIGINT NOT NULL REFERENCES pm_organizations(id),product_id BIGINT NOT NULL REFERENCES pm_products(id),opportunity_ref TEXT NOT NULL,score_version TEXT NOT NULL,score JSONB NOT NULL,evidence_ids BIGINT[] NOT NULL,score_digest CHAR(64) NOT NULL,created_by INTEGER NOT NULL REFERENCES users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(organization_id,product_id,score_digest));
CREATE TABLE IF NOT EXISTS pm_decisions(id BIGSERIAL PRIMARY KEY,organization_id BIGINT NOT NULL REFERENCES pm_organizations(id),product_id BIGINT NOT NULL REFERENCES pm_products(id),idempotency_key TEXT NOT NULL,decision_ref TEXT NOT NULL,opportunity_ref TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('draft','review_pending','approved','external_action_pending','published','ticket_created','measuring','evaluated','failed','rejected','cancelled')),revision INTEGER NOT NULL DEFAULT 1,forecast_version TEXT NOT NULL,forecast JSONB NOT NULL,evidence_ids BIGINT[] NOT NULL,confidential BOOLEAN NOT NULL DEFAULT FALSE,effective_at TIMESTAMPTZ,decision_digest CHAR(64) NOT NULL,created_by INTEGER NOT NULL REFERENCES users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(organization_id,product_id,idempotency_key),UNIQUE(organization_id,product_id,decision_ref),UNIQUE(organization_id,product_id,decision_digest));
CREATE TABLE IF NOT EXISTS pm_approvals(id BIGSERIAL PRIMARY KEY,organization_id BIGINT NOT NULL REFERENCES pm_organizations(id),product_id BIGINT NOT NULL REFERENCES pm_products(id),decision_id BIGINT NOT NULL REFERENCES pm_decisions(id),actor_id INTEGER NOT NULL REFERENCES users(id),decision TEXT NOT NULL CHECK(decision IN('approve','reject')),attestation_digest CHAR(64) NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(organization_id,product_id,decision_id,actor_id));
CREATE TABLE IF NOT EXISTS pm_external_outbox(id BIGSERIAL PRIMARY KEY,organization_id BIGINT NOT NULL REFERENCES pm_organizations(id),product_id BIGINT NOT NULL REFERENCES pm_products(id),decision_id BIGINT NOT NULL REFERENCES pm_decisions(id),provider TEXT NOT NULL,action_type TEXT NOT NULL CHECK(action_type IN('publication','ticket')),idempotency_key TEXT NOT NULL,payload JSONB NOT NULL,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN('pending','processing','retry','delivered','dead_letter')),attempts INTEGER NOT NULL DEFAULT 0,next_attempt_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),external_id TEXT,evidence_digest CHAR(64),last_error_code TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(organization_id,product_id,idempotency_key));
CREATE TABLE IF NOT EXISTS pm_outcome_evaluations(id BIGSERIAL PRIMARY KEY,organization_id BIGINT NOT NULL REFERENCES pm_organizations(id),product_id BIGINT NOT NULL REFERENCES pm_products(id),decision_id BIGINT NOT NULL REFERENCES pm_decisions(id),outcome JSONB NOT NULL,evaluation JSONB NOT NULL,evaluation_digest CHAR(64) NOT NULL,evaluated_by INTEGER NOT NULL REFERENCES users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(organization_id,product_id,decision_id,evaluation_digest));
CREATE TABLE IF NOT EXISTS pm_provider_failures(id BIGSERIAL PRIMARY KEY,organization_id BIGINT NOT NULL REFERENCES pm_organizations(id),product_id BIGINT NOT NULL REFERENCES pm_products(id),decision_id BIGINT REFERENCES pm_decisions(id),provider TEXT NOT NULL,operation TEXT NOT NULL,retryable BOOLEAN NOT NULL,error_code TEXT NOT NULL,sanitized_detail TEXT,occurred_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS pm_data_rights_requests(id BIGSERIAL PRIMARY KEY,organization_id BIGINT NOT NULL REFERENCES pm_organizations(id),product_id BIGINT NOT NULL REFERENCES pm_products(id),request_type TEXT NOT NULL CHECK(request_type IN('export','retention_delete')),subject_ref_digest CHAR(64) NOT NULL,reason TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('pending_approval','approved','rejected','completed')),requested_by INTEGER NOT NULL REFERENCES users(id),reviewed_by INTEGER REFERENCES users(id),review_attestation_digest CHAR(64),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),reviewed_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS pm_events(id BIGSERIAL PRIMARY KEY,organization_id BIGINT NOT NULL REFERENCES pm_organizations(id),product_id BIGINT NOT NULL REFERENCES pm_products(id),decision_id BIGINT REFERENCES pm_decisions(id),actor_id INTEGER REFERENCES users(id),sequence INTEGER NOT NULL,event_type TEXT NOT NULL,payload JSONB NOT NULL,previous_digest CHAR(64),event_digest CHAR(64) NOT NULL,evidence_digest CHAR(64),occurred_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(organization_id,product_id,decision_id,sequence),UNIQUE(organization_id,product_id,event_digest));
CREATE INDEX IF NOT EXISTS pm_evidence_source_idx ON pm_evidence(organization_id,product_id,provider,external_id);
CREATE INDEX IF NOT EXISTS pm_decision_status_idx ON pm_decisions(organization_id,product_id,status,updated_at);
CREATE INDEX IF NOT EXISTS pm_outbox_ready_idx ON pm_external_outbox(status,next_attempt_at);
CREATE OR REPLACE FUNCTION prevent_pm_evidence_mutation() RETURNS trigger AS $$BEGIN RAISE EXCEPTION 'product evidence is append-only';END;$$ LANGUAGE plpgsql;
DROP TRIGGER IF EXISTS pm_workspace_append_only ON pm_workspace_versions;CREATE TRIGGER pm_workspace_append_only BEFORE UPDATE OR DELETE ON pm_workspace_versions FOR EACH ROW EXECUTE FUNCTION prevent_pm_evidence_mutation();
DROP TRIGGER IF EXISTS pm_entities_append_only ON pm_domain_entities;CREATE TRIGGER pm_entities_append_only BEFORE UPDATE OR DELETE ON pm_domain_entities FOR EACH ROW EXECUTE FUNCTION prevent_pm_evidence_mutation();
DROP TRIGGER IF EXISTS pm_evidence_append_only ON pm_evidence;CREATE TRIGGER pm_evidence_append_only BEFORE UPDATE OR DELETE ON pm_evidence FOR EACH ROW EXECUTE FUNCTION prevent_pm_evidence_mutation();
DROP TRIGGER IF EXISTS pm_scores_append_only ON pm_opportunity_scores;CREATE TRIGGER pm_scores_append_only BEFORE UPDATE OR DELETE ON pm_opportunity_scores FOR EACH ROW EXECUTE FUNCTION prevent_pm_evidence_mutation();
DROP TRIGGER IF EXISTS pm_approvals_append_only ON pm_approvals;CREATE TRIGGER pm_approvals_append_only BEFORE UPDATE OR DELETE ON pm_approvals FOR EACH ROW EXECUTE FUNCTION prevent_pm_evidence_mutation();
DROP TRIGGER IF EXISTS pm_evaluations_append_only ON pm_outcome_evaluations;CREATE TRIGGER pm_evaluations_append_only BEFORE UPDATE OR DELETE ON pm_outcome_evaluations FOR EACH ROW EXECUTE FUNCTION prevent_pm_evidence_mutation();
DROP TRIGGER IF EXISTS pm_events_append_only ON pm_events;CREATE TRIGGER pm_events_append_only BEFORE UPDATE OR DELETE ON pm_events FOR EACH ROW EXECUTE FUNCTION prevent_pm_evidence_mutation();
CREATE OR REPLACE FUNCTION guard_pm_decision_evidence() RETURNS trigger AS $$BEGIN IF NEW.organization_id IS DISTINCT FROM OLD.organization_id OR NEW.product_id IS DISTINCT FROM OLD.product_id OR NEW.decision_ref IS DISTINCT FROM OLD.decision_ref OR NEW.opportunity_ref IS DISTINCT FROM OLD.opportunity_ref OR NEW.forecast_version IS DISTINCT FROM OLD.forecast_version OR NEW.forecast IS DISTINCT FROM OLD.forecast OR NEW.evidence_ids IS DISTINCT FROM OLD.evidence_ids OR NEW.confidential IS DISTINCT FROM OLD.confidential OR NEW.effective_at IS DISTINCT FROM OLD.effective_at OR NEW.decision_digest IS DISTINCT FROM OLD.decision_digest OR NEW.created_by IS DISTINCT FROM OLD.created_by OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN RAISE EXCEPTION 'decision evidence cannot be rewritten';END IF;RETURN NEW;END;$$ LANGUAGE plpgsql;
DROP TRIGGER IF EXISTS pm_decision_evidence_guard ON pm_decisions;CREATE TRIGGER pm_decision_evidence_guard BEFORE UPDATE ON pm_decisions FOR EACH ROW EXECUTE FUNCTION guard_pm_decision_evidence();
COMMIT;
